    this.ruvSwarm = await RuvSwarm.initialize({
      loadingStrategy: 'progressive',
      enablePersistence: false, // Disable for tests
      enableNeuralNetworks: true,
      enableForecasting: false, // Start with disabled
      useSIMD: true,
      debug: true,
