      const target = [0.7, 0.3];

      const output = network.train(input, target, 0.1);
      assert(Array.isArray(output));
    });

    it('should update weights during training', () => {
      const input = [0.5, 0.3, 0.2, 0.8];
      const target = [0.7, 0.3];

