  checkNodeCompatibility(version) {
    const major = parseInt(version.slice(1).split('.')[0], 10);
    return major >= 14; // Minimum Node.js 14
  }

  generateRecommendations() {
    const recommendations = [];

    this.testResults.tests.forEach(test => {
