// Test configuration
const MCP_SERVER_URL = 'ws://localhost:3000/mcp';
const HTTP_BASE_URL = 'http://localhost:3000';
const TEST_TIMEOUT = 60000; // 60 seconds

// Test utilities
class MCPTestClient {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.requestId = 0;
    this.pendingRequests = new Map();
    this.notifications = [];
    this.connected = false;
  }

  async connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.url);

      this.ws.on('open', () => {
        console.log('Connected to MCP server');
        resolve();
      });

      this.ws.on('message', (data) => {
        const message = JSON.parse(data.toString());

        if (message.id && this.pendingRequests.has(message.id)) {
          const { resolve, reject } = this.pendingRequests.get(message.id);
          this.pendingRequests.delete(message.id);

          if (message.error) {
            reject(new Error(message.error.message));
          } else {
            resolve(message.result);
          }
        } else if (message.method) {
          // Notification
          this.notifications.push(message);
        }
      });

      this.ws.on('error', (error) => {
        console.error('WebSocket error:', error.message);
        reject(new Error(`MCP server connection failed: ${error.message}`));
      });

      this.ws.on('close', () => {
        console.log('Disconnected from MCP server');
        this.connected = false;
      });

      // Set connection timeout
      setTimeout(() => {
        if (this.ws && this.ws.readyState !== WebSocket.OPEN) {
          this.ws.close();
          reject(new Error('Connection timeout - MCP server may not be running'));
        }
      }, 5000);
    });
  }

  async disconnect() {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  async sendRequest(method, params = null) {
    const id = ++this.requestId;
    const request = {
      jsonrpc: '2.0',
      id,
      method,
      params,
    };

    return new Promise((resolve, reject) => {
      this.pendingRequests.set(id, { resolve, reject });
      this.ws.send(JSON.stringify(request));

      // Timeout after 30 seconds
      setTimeout(() => {
        if (this.pendingRequests.has(id)) {
          this.pendingRequests.delete(id);
          reject(new Error(`Request ${id} timed out`));
        }
      }, 30000);
    });
  }

  clearNotifications() {
    this.notifications = [];
  }

  getNotifications(filter = null) {
    if (!filter) {
      return this.notifications;
    }
    return this.notifications.filter(n => n.method === filter);
  }
}

