          const weights = layer.weights.flat();
          const mean = weights.reduce((a, b) => a + b) / weights.length;
          const variance = weights.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / weights.length;

          expect(Math.abs(mean)).toBeLessThan(0.1);
